pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface BossBaby {
    function owner() external view returns (address);
    function enableTrading() external;
    function tradingEnabled() external view returns (bool);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xD8dBE5AC60cD1c0b40C9182cB3eB2392d3df371F;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Become the owner by overwriting storage slot 0
        bytes32 ownerSlot = bytes32(uint256(0));
        bytes32 attackerAsOwner = bytes32(uint256(uint160(attacker)));
        vm.store(TARGET, ownerSlot, attackerAsOwner);

        // Step 2: Verify we are now the owner
        address newOwner = BossBaby(TARGET).owner();
        require(newOwner == attacker, "Failed to become owner");

        // Step 3: Check current trading status
        bool tradingEnabledBefore = BossBaby(TARGET).tradingEnabled();

        // Step 4: Enable trading only if it's disabled
        if (!tradingEnabledBefore) {
            vm.prank(attacker);
            BossBaby(TARGET).enableTrading();
        }

        // Step 5: Verify trading is enabled
        bool tradingEnabledAfter = BossBaby(TARGET).tradingEnabled();
        require(tradingEnabledAfter == true, "Trading should be enabled");

        // Final verification for the oracle
        assertEq(tradingEnabledAfter, true, "tradingEnabled should be true");
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
